function buildPageNumbers4(current, total) {
  if (total <= 9)
    return Array.from({ length: total }, (_, i) => i + 1);
  const pages = [];
  let prev = 0;
  for (let i = 1; i <= total; i++) {
    if (i === 1 || i === total || i >= current - 2 && i <= current + 2) {
      if (prev && i - prev > 1)
        pages.push(-1);
      pages.push(i);
      prev = i;
    }
  }
  return pages;
}

