        this.emp.set(match);
        this.form.patchValue({
          otherAddition: match.otherAddition ?? 0,
          otherAdditionNote: match.otherAdditionNote ?? "",
          otherDeduction: match.otherDeduction ?? 0,
          otherDeductionNote: match.otherDeductionNote ?? "",
          note: match.note ?? ""
        });
        this.loading.set(false);
